propuesta.texto_nuevo:
funciones_encontradas = set()
# Primero, buscamos nombres que empiezan por _ (como funciones internas)
for palabra in texto_encargo.replace(",", " ").replace(";", " ").split():
    limpia = palabra.strip("()[]{}<>\"'`.:")
    if limpia.startswith("_") and len(limpia) > 1:
        corte = len(limpia)
        for _i, _c in enumerate(limpia):
            if not (_c.isalnum() or _c == "_"):
                corte = _i
                break
        nombre = limpia[:corte]
        if nombre.startswith("_") and len(nombre) > 1:
            funciones_encontradas.add(nombre)

# Luego, si hay lista de conocidas, buscamos esas palabras, pero SOLO si vienen despues de 'def' o 'funcion'
if conocidas:
    palabras_del_texto = texto_encargo.replace(",", " ").replace(";", " ").split()
    for i, palabra in enumerate(palabras_del_texto):
        limpia = palabra.strip("()[]{}<>\"'`.:")
        # Verificamos si la palabra es una funcion declarada
        es_funcion_declarada = False
        if i > 0:
            palabra_anterior = palabras_del_texto[i-1].strip("()[]{}<>\"'`.:")
            if palabra_anterior == "def" or palabra_anterior == "funcion":
                es_funcion_declarada = True

        # Si es una funcion declarada y está en las conocidas, la añadimos
        if es_funcion_declarada and limpia in conocidas:
            funciones_encontradas.add(limpia)
        # Si no es una funcion declarada, pero está en las conocidas y no tiene comillas, la añadimos
        # Esto cubre el caso 5 donde palabras con _ no necesitan ser declaradas
        elif limpia in conocidas and limpia not in funciones_encontradas and not ('"' in palabra or "'" in palabra or '`' in palabra):
             funciones_encontradas.add(limpia)

return list(funciones_encontradas)

